Here is the root cause:
The bug arises because the RPS (Runtime Power Saving) interrupts are cleared and disabled on module load, but the interrupt mask is cleared on suspend. This means that after a system resume, the interrupts may be unexpectedly re-enabled, leading to potential issues in the power management behavior of the GPU.

Here is the patch:

 static void gt_sanitize(struct intel_gt *gt, bool force)
 {
 	struct intel_engine_cs *engine;
 	enum intel_engine_id id;
 	intel_wakeref_t wakeref;

 	GT_TRACE(gt, "force:%s", yesno(force));

 	/* Use a raw wakeref to avoid calling intel_display_power_get early */
 	wakeref = intel_runtime_pm_get(gt->uncore->rpm);
 	intel_uncore_forcewake_get(gt->uncore, FORCEWAKE_ALL);

 	intel_gt_check_clock_frequency(gt);

 	/*
 	 * As we have just resumed the machine and woken the device up from
 	 * deep PCI sleep (presumably D3_cold), assume the HW has been reset
 	 * back to defaults, recovering from whatever wedged state we left it
 	 * in and so worth trying to use the device once more.
 	 */
 	if (intel_gt_is_wedged(gt))
 		intel_gt_unset_wedged(gt);

 	for_each_engine(engine, gt, id)
 		if (engine->sanitize)
 			engine->sanitize(engine);

 	intel_uc_sanitize(&gt->uc);

 	for_each_engine(engine, gt, id)
 		if (engine->reset.prepare)
 			engine->reset.prepare(engine);

 	intel_uc_reset_prepare(&gt->uc);

 	if (reset_engines(gt) || force) {
 		for_each_engine(engine, gt, id)
 			__intel_engine_reset(engine, false);
 	}

 	for_each_engine(engine, gt, id)
 		if (engine->reset.finish)
 			engine->reset.finish(engine);

+	intel_rps_sanitize(&gt->rps);
+
 	intel_uncore_forcewake_put(gt->uncore, FORCEWAKE_ALL);
 	intel_runtime_pm_put(gt->uncore->rpm, wakeref);
 }



